entries[703] = { ["name"] = "Garrote", ["text"] = "45 Energy Melee Range\nInstant\nRequires Stealth\nGarrote the enemy, silencing them for 3 sec and causing [( 147 + Attack Power * 0.078) * 6] damage over 18 sec, increased by your attack power. Must be stealthed. Awards 1 combo point [ Cloak and Dagger : and causes you to appear behind the target ]." }
entries[710] = { ["name"] = "Banish", ["text"] = "30 Demonic Fury / 3% of base mana 30 yd range\n1.5 sec cast\nBanishes an enemy Demon, Aberration or Elemental for up to 30 sec.\n\nBanished\nThe target cannot act but is invulnerable. Limit 1 target.\n\nCasting Banish again will cancel the spell." }
entries[712] = { ["name"] = "Summon Succubus", ["text"] = "20% of base demonic fury / 25% of base mana\n5 sec cast\nSummons a Succubus under the command of the Warlock.\n\nSuccubi are dangerous, close-range spellcasters. They [ Succubus: Lesser Invisibility : turn invisible ] [ Succubus: Whiplash : knock away enemies ] [ Succubus: Lesser Invisibility : and ] seduce Humanoid creatures, preventing them from attacking. [ Soulburn : Soulburn:\nInstant cast. ]" }
entries[713] = { ["name"] = "Summon Incubus", ["text"] = "25% of base mana / 20% of base demonic fury\n5 sec cast\nSummons an Incubus under the command of the Warlock.\n\nIncubi are dangerous, close-range spellcasters. They [ Succubus: Lesser Invisibility : turn invisible ] [ Succubus: Whiplash : knock away enemies ] [ Succubus: Lesser Invisibility : and ] seduce Humanoid creatures, preventing them from attacking. [ Soulburn : Soulburn:\nInstant cast. ]" }
entries[720] = { ["name"] = "Entangle", ["text"] = "Instant\nThe lair of Fankriss the Unyielding pulls the target into the path of nearby silithid hatchlings, rooting it for 8 sec." }
entries[724] = { ["name"] = "Lightwell", ["text"] = "5.4% of base mana 40 yd range\n0.5 sec cast 3 min cooldown\nCreates a Holy Lightwell. Friendly players can click the Lightwell to restore [(( 5735 + (Spell Power * .553))) * 1.5] health every 2 sec for 6 sec. Attacks done to you equal to 30% of your total health will cancel the effect. Lightwell lasts for 3 min or 15 charges." }
