entries[740] = { ["name"] = "Tranquility", ["text"] = "27.1% of base mana\nChanneled (8 sec cast) 8 min cooldown\nHeals 5 (12 in 25 player instances) nearby lowest health party or raid targets within 40 yards with Tranquility every 2 sec for 8 sec.\n\nTranquility heals for 9037 plus an additional 1 every 2 sec over 8 sec. Stacks up to 3 times. The Druid must channel to maintain the spell." }
