entries[755] = { ["name"] = "Health Funnel", ["text"] = "45 yd range\nChanneled (6 sec cast)\nSacrifices 2% of your maximum health to restore 6% of your summoned Demon's maximum health every 1 sec. Lasts for 6 sec.\n[\nEmpowered Channel\nRecasting this spell before it finishes boosts the duration by 0.05 sec.\nStacks 0 times. ] [ Soulburn: Health Funnel : Soulburn:\nRestores 140% more health and reduces damage taken by 30% for 10 sec. ]" }
entries[759] = { ["name"] = "Conjure Mana Gem", ["text"] = "18% of base mana\n3 sec cast\nConjures a Mana Gem that can be used to [ Glyph of Loose Mana : restore 0 mana over until cancelled / instantly restore 45000 mana], and holds up to 3 charges.\n\nConjured Items\nConjured items disappear if logged out for more than 15 minutes." }
entries[768] = { ["name"] = "Cat Form", ["text"] = "3.7% of base mana\nInstant\nShapeshift into Cat Form, causing Agility to increase attack power, increasing autoattack damage by 100%, and increasing movement speed by 25% (cumulative with most other movement speed increases). [ Glyph of Cat Form : Additionally, all healing done to you is increased by 20% ]\nAlso protects the caster from Polymorph effects and allows the use of various cat abilities.\n\nEnergy regeneration continues while not in Cat Form.\n\nThe act of shapeshifting frees the caster of movement impairing effects." }
entries[770] = { ["name"] = "Faerie Fire", ["text"] = "7.5% of base mana 35 yd range\nInstant\nFaeries surround the target, preventing it from stealthing or turning invisible, and causing 3 applications of the Weakened Armor debuff.\n\nDeals 10 damage [ Glyph of Fae Silence : silences for 3 sec ] and has a 25% chance to reset the cooldown on Mangle when cast from Bear Form.\n\nWeakened Armor\nWeakens the armor of the target by 4% for 30 sec. Stacks up to 3 times." }
entries[774] = { ["name"] = "Rejuvenation", ["text"] = "14.5% of base mana 40 yd range\nInstant\nHeals the target for 1 and an additional 1 every 3 sec for 12 sec." }
entries[779] = { ["name"] = "Swipe", ["text"] = "15 Rage 8 yd range\nInstant cast 3 sec cooldown\nRequires Bear Form\nSwipe nearby enemies, inflicting 246 damage.\n\nDeals 20% increased damage against bleeding targets." }
entries[781] = { ["name"] = "Disengage", ["text"] = "Unlimited range\nInstant 20 sec cooldown\nYou attempt to leap backwards [ Posthaste : clearing movement impairing effects, and increasing your movement speed by 60% for 8 sec ] [ Narrow Escape : and activating a web trap which encases all targets within 8 yards in sticky webs, preventing movement for 8 sec ]. [ Glyph of Liberation : Restores 5% of your maximum health ]" }
entries[783] = { ["name"] = "Travel Form", ["text"] = "5.6% of base mana\nInstant\nShapeshift into travel form, increasing movement speed by 40%. Also protects the caster from Polymorph effects. Only useable outdoors.\n\nThe act of shapeshifting frees the caster of movement impairing effects." }
entries[785] = { ["name"] = "True Fulfillment", ["text"] = "260 Mana 45 yd range\n0.5 sec cast\nConverted by the powers of the Prophet Skeram, the target is converted and filled with divine power. While converted, the target's spells are cast instantly, damage is increased by 300%, all resistances increased by 50 and movement speed is increased by 40%. Lasts 20 sec." }
