entries[974] = { ["name"] = "Earth Shield", ["text"] = "19% of base mana 40 yd range\nInstant\nProtects the target with an earthen shield, increasing the effectiveness of Shaman healing spells on that target by 20%, and causing attacks to heal the shielded target for ( 2043 + Spell Power * 0.13) . 9 charges. Lasts 10 min. This effect can only occur once every few seconds.\n\nEarth Shield can only be placed on one target at a time, only one Earth Shield may be on a target at a time, and only one of your Elemental Shields can be active on you at once.\n(3.5s cooldown)" }
entries[980] = { ["name"] = "Agony", ["text"] = "1% of base mana 40 yd range\nInstant\nInflicts increasing agony on the target, causing up to ( 327 * 10) Shadow damage over 24 sec.\n\nThis damage is dealt slowly at first and builds up each time it deals damage." }
