entries[1022] = { ["name"] = "Hand of Protection", ["text"] = "7% of base mana 40 yd range\nInstant 5 min cooldown\nPlaces a Hand on a party or raid member, protecting them from all physical attacks for 10 sec, but during that time they cannot attack or use physical abilities. Players may only have one Hand on them per Paladin at any one time.\n\nCannot be used on a target with Forbearance. Causes Forbearance for 1 min." }
entries[1038] = { ["name"] = "Hand of Salvation", ["text"] = "6% of base mana 40 yd range\nInstant 2 min cooldown\nPlaces a Hand on the party or raid member, temporarily removing all their threat for 10 sec. Players may only have one Hand on them per Paladin at any one time." }
entries[1044] = { ["name"] = "Hand of Freedom", ["text"] = "7% of base mana 40 yd range\nInstant 25 sec cooldown\nPlaces a Hand on the friendly target, granting immunity to movement impairing effects for 6 sec. Players may only have one Hand on them per Paladin at any one time." }
