entries[1064] = { ["name"] = "Chain Heal", ["text"] = "22.5% of base mana 40 yd range\n2.5 sec cast\nHeals the friendly target for 7590 , then jumps to heal the most injured nearby targets. If cast on a party or raid member, the heal will only jump to other members. [ Restoration : While outside of Arenas and Battlegrounds, each jump reduces the effectiveness of the heal by 20% ] Heals 4 total targets." }
entries[1066] = { ["name"] = "Aquatic Form", ["text"] = "5.6% of base mana\nInstant\nShapeshift into aquatic form, increasing swim speed by 50% and allowing the Druid to breathe underwater. Also protects the caster from Polymorph effects.\n\nThe act of shapeshifting frees the caster of movement impairing effects." }
entries[1079] = { ["name"] = "Rip", ["text"] = "30 Energy Melee Range\nInstant\nRequires Cat Form\nFinishing move that causes Bleed damage over time. Damage increases per combo point:\n\n1 point : [floor(((((4 + (Attack Power * 0.0484)))) * (( 1 * 1 * 1 * 1 * 1 ))) + 113 ) * 8] damage over 16 sec.\n2 points: [floor(((((4 + (Attack Power * 0.0484))) * 2) * (( 1 * 1 * 1 * 1 * 1 ))) + 113 ) * 8] damage over 16 sec.\n3 points: [floor(((((4 + (Attack Power * 0.0484))) * 3) * (( 1 * 1 * 1 * 1 * 1 ))) + 113 ) * 8] damage over 16 sec.\n4 points: [floor(((((4 + (Attack Power * 0.0484))) * 4) * (( 1 * 1 * 1 * 1 * 1 ))) + 113 ) * 8] damage over 16 sec.\n5 points: [floor(((((4 + (Attack Power * 0.0484))) * 5) * (( 1 * 1 * 1 * 1 * 1 ))) + 113 ) * 8] damage over 16 sec.\n\nEach time you Shred, Ravage, or Mangle the target while in Cat Form the duration of your Rip on that target is extended by 2 sec, up to a maximum of 6 sec." }
entries[1090] = { ["name"] = "Sleep", ["text"] = "90 Mana 30 yd range\n1.5 sec cast\nPuts the enemy target to sleep for up to 30 sec. Any damage caused will awaken the target. Only one target can be asleep at a time. Unreliable on targets above level 30." }
entries[1098] = { ["name"] = "Subjugate Demon", ["text"] = "5% of base mana 30 yd range\n3 sec cast\nSubjugates the target demon, forcing it to do your bidding. Lasts up to 5 min.\n\nSubjugated\nWhile subjugated, the time between the demon's attacks is increased by 30% and its casting speed is slowed by 20%." }
entries[1120] = { ["name"] = "Drain Soul", ["text"] = "1.5% of base mana , plus 1.5% per second 40 yd range\nChanneled (12 sec cast)\nDrains the soul of the target, causing ( 275 + Spell Power * 0.257) Shadow damage every 2 sec and energizing one Soul Shard after it deals damage twice. If the target dies and yields experience or honor, 4 Soul Shards are energized. Lasts 12 sec.\n\nIf the target is at or below 20% health when Drain Soul deals damage, it deals 100% additional damage and causes all of your other periodic Affliction damage effects to instantly deal 60% of their normal periodic damage." }
