entries[1122] = { ["name"] = "Summon Infernal", ["text"] = "25% of base mana 30 yd range\nInstant 10 min cooldown\nSummons a meteor from the Twisting Nether, causing 1069 Fire damage and stunning all enemy targets in the area for 2 sec. An Infernal rises from the crater, under the command of the caster for 1 min.\n\nThe Infernal deals strong area of effect damage, and will be drawn to attack targets near the impact point." }
